type Shape interface{ isShape() }        // unexported marker => closed set
func (*Circle) isShape() {}               // only this package can implement it
func (*Rect) isShape()   {}

func Area(s Shape) float64 {
    switch v := s.(type) {                // //sumtype:decl + go-check-sumtype
    case *Circle:
        return math.Pi * v.R * v.R
    case *Rect:
        return v.W * v.H
    }
    panic("unhandled shape")              // nil or a new variant
}
